17	package org.springframework.samples.petclinic.rest.controller.v1;
18	
19	import java.time.LocalDate;
20	import java.util.Collection;
21	import java.util.List;
22	import java.util.Locale;
23	import java.util.Objects;
24	
25	import org.springframework.http.HttpHeaders;
26	import org.springframework.http.HttpStatus;
27	import org.springframework.http.ResponseEntity;
28	import org.springframework.samples.petclinic.mapper.OwnerMapper;
29	import org.springframework.samples.petclinic.mapper.PetMapper;
30	import org.springframework.samples.petclinic.mapper.VisitMapper;
31	import org.springframework.samples.petclinic.model.Owner;
32	import org.springframework.samples.petclinic.model.Pet;
33	import org.springframework.samples.petclinic.model.Visit;
34	import org.springframework.samples.petclinic.rest.api.OwnersApi;
35	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
36	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
37	import org.springframework.samples.petclinic.rest.dto.PetDto;
38	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
39	import org.springframework.samples.petclinic.rest.dto.VisitDto;
40	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
41	import org.springframework.samples.petclinic.service.ClinicService;
42	import org.springframework.security.access.prepost.PreAuthorize;
43	import org.springframework.web.bind.annotation.CrossOrigin;
44	import org.springframework.web.bind.annotation.RequestMapping;
45	import org.springframework.web.bind.annotation.RestController;
46	import org.springframework.web.util.UriComponentsBuilder;
47	
48	import jakarta.transaction.Transactional;
49	
50	/**
51	 * @author Vitaliy Fedoriv
52	 */
53	
54	@RestController
55	@CrossOrigin(exposedHeaders = "errors, content-type")
56	@RequestMapping("/api")
57	public class OwnerRestControllerV1 implements OwnersApi {
58	
59	    private final ClinicService clinicService;
60	
61	    private final OwnerMapper ownerMapper;
62	
63	    private final PetMapper petMapper;
64	
65	    private final VisitMapper visitMapper;
66	
67	    public OwnerRestControllerV1(ClinicService clinicService,
68	                                 OwnerMapper ownerMapper,
69	                                 PetMapper petMapper,
70	                                 VisitMapper visitMapper) {
71	        this.clinicService = clinicService;
72	        this.ownerMapper = ownerMapper;
73	        this.petMapper = petMapper;
74	        this.visitMapper = visitMapper;
75	    }
76	
77	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
78	    @Override
79	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
80	        Collection<Owner> owners;
81	        if (lastName != null) {
82	            owners = this.clinicService.findOwnerByLastName(lastName);
83	        } else {
84	            owners = this.clinicService.findAllOwners();
85	        }
86	        if (owners.isEmpty()) {
87	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
88	        }
89	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
90	    }
91	
92	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
93	    @Override
94	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
95	        Owner owner = this.clinicService.findOwnerById(ownerId);
96	        if (owner == null) {
97	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
98	        }
99	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
100	    }
101	
102	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
103	    @Override
104	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
105	        HttpHeaders headers = new HttpHeaders();
106	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
107	        if (owner.getRegistrationDate() == null) {
108	            owner.setRegistrationDate(LocalDate.now());
109	        }
110	        if (isDuplicateOwner(owner) || isDuplicateEmail(owner)) {
111	            return new ResponseEntity<>(HttpStatus.CONFLICT);
112	        }
113	        owner.setMembershipNumber(this.clinicService.findAllOwners().size() + 1);
114	        owner.setCustomerCode(customerCode(owner));
115	        this.clinicService.saveOwner(owner);
116	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
117	        headers.setLocation(UriComponentsBuilder.newInstance()
118	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
119	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
120	    }
121	
122	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
123	    @Override
124	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
125	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
126	        if (currentOwner == null) {
127	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
128	        }
129	        currentOwner.setAddress(ownerFieldsDto.getAddress());
130	        currentOwner.setCity(ownerFieldsDto.getCity());
131	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
132	        currentOwner.setLastName(ownerFieldsDto.getLastName());
133	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
134	        this.clinicService.saveOwner(currentOwner);
135	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
136	    }
137	
138	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
139	    @Transactional
140	    @Override
141	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
142	        Owner owner = this.clinicService.findOwnerById(ownerId);
143	        if (owner == null) {
144	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
145	        }
146	        this.clinicService.deleteOwner(owner);
147	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
148	    }
149	
150	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
151	    @Override
152	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
153	        Owner owner = this.clinicService.findOwnerById(ownerId);
154	        if (owner == null) {
155	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
156	        }
157	        HttpHeaders headers = new HttpHeaders();
158	        Pet pet = petMapper.toPet(petFieldsDto);
159	        owner.setId(ownerId);
160	        pet.setOwner(owner);
161	        pet.getType().setName(null);
162	        this.clinicService.savePet(pet);
163	        PetDto petDto = petMapper.toPetDto(pet);
164	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
165	            .buildAndExpand(pet.getId()).toUri());
166	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
167	    }
168	
169	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
170	    @Override
171	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
172	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
173	        if (currentOwner != null) {
174	            Pet currentPet = this.clinicService.findPetById(petId);
175	            if (currentPet != null) {
176	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
177	                currentPet.setName(petFieldsDto.getName());
178	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
179	                this.clinicService.savePet(currentPet);
180	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
181	            }
182	        }
183	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
184	    }
185	
186	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
187	    @Override
188	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
189	        HttpHeaders headers = new HttpHeaders();
190	        Visit visit = visitMapper.toVisit(visitFieldsDto);
191	        Pet pet = new Pet();
192	        pet.setId(petId);
193	        visit.setPet(pet);
194	        this.clinicService.saveVisit(visit);
195	        VisitDto visitDto = visitMapper.toVisitDto(visit);
196	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
197	            .buildAndExpand(visit.getId()).toUri());
198	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
199	    }
200	
201	
202	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
203	    @Override
204	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
205	        Owner owner = this.clinicService.findOwnerById(ownerId);
206	        if (owner != null) {
207	            Pet pet = owner.getPet(petId);
208	            if (pet != null) {
209	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
210	            }
211	        }
212	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
213	    }
214	
215	    /**
216	     * Determines whether an owner conflicting with the given one already exists, i.e. any existing
217	     * owner using the same telephone number.
218	     *
219	     * @param owner the candidate owner to check
220	     * @return {@code true} if another owner already uses the telephone number, {@code false} otherwise
221	     */
222	    /**
223	     * Builds the customer code assigned to a newly created owner, formatted as
224	     * {@code '<UPPERCASE_CITY>-<NNNN>'} where {@code NNNN} is one more than the number of owners
225	     * already registered in the same city, zero-padded to four digits (e.g. {@code 'LONDON-0007'}).
226	     *
227	     * @param owner the owner being created
228	     * @return the customer code for the owner
229	     */
230	    private String customerCode(Owner owner) {
231	        String city = owner.getCity();
232	        long existingInCity = this.clinicService.findAllOwners().stream()
233	            .filter(existing -> Objects.equals(existing.getCity(), city))
234	            .count();
235	        return String.format("%s-%04d", city.toUpperCase(Locale.ROOT), existingInCity + 1);
236	    }
237	
238	    private boolean isDuplicateOwner(Owner owner) {
239	        return this.clinicService.findAllOwners().stream()
240	            .anyMatch(existing -> Objects.equals(existing.getTelephone(), owner.getTelephone()));
241	    }
242	
243	    /**
244	     * Determines whether the given owner's email address is already used by another owner. An owner
245	     * without an email address never conflicts. The comparison is case-insensitive and ignores
246	     * surrounding or repeated whitespace, so e.g. {@code "  John.Smith@Example.com "} and
247	     * {@code "john.smith@example.com"} are treated as the same address.
248	     *
249	     * @param owner the candidate owner to check
250	     * @return {@code true} if another owner already uses the email address, {@code false} otherwise
251	     */
252	    private boolean isDuplicateEmail(Owner owner) {
253	        String email = normalize(owner.getEmail());
254	        if (email == null || email.isEmpty()) {
255	            return false;
256	        }
257	        return this.clinicService.findAllOwners().stream()
258	            .anyMatch(existing -> email.equals(normalize(existing.getEmail())));
259	    }
260	
261	    /**
262	     * Normalises a value for case- and whitespace-insensitive duplicate detection: surrounding
263	     * whitespace is stripped, any run of internal whitespace is collapsed to a single space and all
264	     * letters are lower-cased. This is what makes {@code "  john   smith "} and {@code "John Smith"}
265	     * count as the same person (or, for e-mail, the same address) when detecting duplicates.
266	     *
267	     * @param value the raw value, may be {@code null}
268	     * @return the normalised value, or {@code null} if {@code value} was {@code null}
269	     */
270	    private static String normalize(String value) {
271	        if (value == null) {
272	            return null;
273	        }
274	        return value.strip().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
275	    }
276	}
